use super::*;

pub(crate) fn tally(name: &str, about: &str, kind: Kind, values: impl Iterator<Item = String>) -> Dist {
    let mut counts: BTreeMap<String, u64> = BTreeMap::new();
    let mut n = 0u64;
    for v in values {
        *counts.entry(v).or_insert(0) += 1;
        n += 1;
    }
    Dist { name: name.into(), about: about.into(), kind, counts, n }
}
